const createInterventionTask = `-- name: CreateInterventionTask :one
INSERT INTO intervention_tasks (org_id, student_id, reasons, status)
VALUES ($1, $2, $3, $4)
ON CONFLICT (org_id, student_id) WHERE status <> 'Resolved' DO NOTHING
RETURNING id, org_id, student_id, reasons, status, resolution_comment, assigned_to, escalated_at, created_at, resolved_at
`

type CreateInterventionTaskParams struct {
	OrgID     uuid.UUID `json:"org_id"`
	StudentID uuid.UUID `json:"student_id"`
	Reasons   []string  `json:"reasons"`
	Status    string    `json:"status"`
}

// ON CONFLICT DO NOTHING (against the one-open-per-student partial index) makes this
// idempotent WITHOUT raising 23505, which would otherwise abort the surrounding tx.
// A conflict (a task is already open) returns no row → pgx.ErrNoRows for the caller.
func (q *Queries) CreateInterventionTask(ctx context.Context, arg CreateInterventionTaskParams) (InterventionTask, error) {
	row := q.db.QueryRow(ctx, createInterventionTask,
		arg.OrgID,
		arg.StudentID,
		arg.Reasons,
		arg.Status,
	)
	var i InterventionTask
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.StudentID,
		&i.Reasons,
		&i.Status,
		&i.ResolutionComment,
		&i.AssignedTo,
		&i.EscalatedAt,
		&i.CreatedAt,
		&i.ResolvedAt,
	)
	return i, err
}

