const expensesByCategory = `-- name: ExpensesByCategory :many
SELECT category, COALESCE(SUM(amount), 0)::bigint AS total
FROM expenses
WHERE org_id = $1 AND spent_at >= $2 AND spent_at <= $3
GROUP BY category
ORDER BY total DESC
`

type ExpensesByCategoryParams struct {
	OrgID     uuid.UUID   `json:"org_id"`
	SpentAt   pgtype.Date `json:"spent_at"`
	SpentAt_2 pgtype.Date `json:"spent_at_2"`
}

type ExpensesByCategoryRow struct {
	Category string `json:"category"`
	Total    int64  `json:"total"`
}

func (q *Queries) ExpensesByCategory(ctx context.Context, arg ExpensesByCategoryParams) ([]ExpensesByCategoryRow, error) {
	rows, err := q.db.Query(ctx, expensesByCategory, arg.OrgID, arg.SpentAt, arg.SpentAt_2)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ExpensesByCategoryRow{}
	for rows.Next() {
		var i ExpensesByCategoryRow
		if err := rows.Scan(&i.Category, &i.Total); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const financeSummary = `-- name: FinanceSummary :one
SELECT
  COALESCE((SELECT SUM(amount) FROM payments WHERE org_id = $1::uuid AND paid_at::date = CURRENT_DATE), 0)::bigint AS today_income,
  COALESCE((SELECT SUM(amount) FROM payments WHERE org_id = $1::uuid AND date_trunc('month', paid_at) = date_trunc('month', CURRENT_DATE)), 0)::bigint AS month_income,
  COALESCE((SELECT SUM(amount - paid_amount) FROM invoices WHERE org_id = $1::uuid AND paid_amount < amount), 0)::bigint AS total_debt,
  COALESCE((SELECT SUM(amount) FROM expenses WHERE org_id = $1::uuid AND spent_at::date = CURRENT_DATE), 0)::bigint AS today_expense,
  COALESCE((SELECT SUM(amount) FROM expenses WHERE org_id = $1::uuid AND date_trunc('month', spent_at) = date_trunc('month', CURRENT_DATE)), 0)::bigint AS month_expense
`

type FinanceSummaryRow struct {
	TodayIncome  int64 `json:"today_income"`
	MonthIncome  int64 `json:"month_income"`
	TotalDebt    int64 `json:"total_debt"`
	TodayExpense int64 `json:"today_expense"`
	MonthExpense int64 `json:"month_expense"`
}

func (q *Queries) FinanceSummary(ctx context.Context, dollar_1 uuid.UUID) (FinanceSummaryRow, error) {
	row := q.db.QueryRow(ctx, financeSummary, dollar_1)
	var i FinanceSummaryRow
	err := row.Scan(
		&i.TodayIncome,
		&i.MonthIncome,
		&i.TotalDebt,
		&i.TodayExpense,
		&i.MonthExpense,
	)
	return i, err
}

const generateMonthlyInvoices = `-- name: GenerateMonthlyInvoices :execrows
INSERT INTO invoices (org_id, student_id, group_id, amount, due_date, period, note)
SELECT m.org_id, m.student_id, m.group_id, c.price, ($1::text || '-10')::date, $1::text, 'Oylik to''lov'
FROM group_members m
JOIN students s ON s.id = m.student_id AND s.status = 'active'
JOIN groups g ON g.id = m.group_id
JOIN courses c ON c.id = g.course_id AND c.price > 0
WHERE NOT EXISTS (
  SELECT 1 FROM invoices i
  WHERE i.student_id = m.student_id AND i.group_id = m.group_id AND i.period = $1::text
)
`

// Bill every active group member for @period (YYYY-MM) at their group's course price, skipping
// anyone already invoiced for that group+period. Idempotent — safe to run repeatedly. Due on the
// 10th. Returns the number of invoices created.
func (q *Queries) GenerateMonthlyInvoices(ctx context.Context, period string) (int64, error) {
	result, err := q.db.Exec(ctx, generateMonthlyInvoices, period)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

